const str={type:'string'},arr=items=>({type:'array',items}),obj=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const base={id:str,refs:arr(str)};
export const planSchema=obj({kind:{type:'string',enum:['plan','clarification']},name:str,summary:str,questions:arr(str),assumptions:arr(str),requirements:arr(obj({id:str,quote:str,text:str})),roles:arr(obj({id:str,name:str})),processes:arr(obj({id:str,name:str,root:str})),main:str,blocks:arr({anyOf:[obj({...base,kind:{type:'string',enum:['action']},name:str,role:str,actor:{type:'string',enum:['user','service','receive','send','manual']},data:arr(str)}),obj({...base,kind:{type:'string',enum:['sequence']},steps:arr(str)}),obj({...base,kind:{type:'string',enum:['choice']},question:str,role:str,branches:arr(obj({label:str,step:str}))}),obj({...base,kind:{type:'string',enum:['parallel']},role:str,branches:arr(str)}),obj({...base,kind:{type:'string',enum:['repeat']},body:str,redo:str,question:str,role:str,again:str,done:str}),obj({...base,kind:{type:'string',enum:['call']},process:str,name:str,role:str}),obj({...base,kind:{type:'string',enum:['wait']},name:str,role:str,timerType:{type:'string',enum:['duration','date']},expression:str}),obj({...base,kind:{type:'string',enum:['watch']},name:str,role:str,trigger:str,body:str,onTimeout:str,duration:str,endCondition:str}),obj({...base,kind:{type:'string',enum:['finish']},name:str,role:str})]}),annotations:arr(obj({text:str,scope:str,refs:arr(str)}))});
export function durationLabel(value){const m=/^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(value);if(!m)return value;return [m[1]&&m[1]+' дн.',m[2]&&m[2]+' ч.',m[3]&&m[3]+' мин.',m[4]&&m[4]+' сек.'].filter(Boolean).join(' ')||value}
planSchema.properties.blocks.items.anyOf.push(obj({...base,kind:{type:'string',enum:['start']},name:str,role:str}));
planSchema.properties.blocks.items.anyOf.find(v=>v.properties.kind.enum[0]==='call').properties.data=arr(str);
planSchema.properties.blocks.items.anyOf.push(obj({...base,kind:{type:'string',enum:['gate']},name:str,role:str,gateway:{type:'string',enum:['exclusive','parallel']}}),obj({...base,kind:{type:'string',enum:['graph']},steps:arr(str),entry:str,flows:arr(obj({source:str,target:str,label:str})),exits:arr(obj({step:str,label:str}))}));
const durationOK=v=>/^P(?=.+)(?:\d+(?:\.\d+)?Y)?(?:\d+(?:\.\d+)?M)?(?:\d+(?:\.\d+)?W)?(?:\d+(?:\.\d+)?D)?(?:T(?=.+)(?:\d+(?:\.\d+)?H)?(?:\d+(?:\.\d+)?M)?(?:\d+(?:\.\d+)?S)?)?$/.test(v)&&/\d/.test(v);
