const clean=(s,max,label,empty=false)=>{if(typeof s!=='string'||s.length>max||(!empty&&!s.trim())||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(s))throw fail('Некорректное поле: '+label);return s.trim()};
export const normalizeText=s=>String(s||'').replace(/[«»“”]/g,'"').replace(/\s+/g,' ').trim();
