export function projectRules(description){return /холд/i.test(description)&&/30\s*мин/i.test(description)?'Правило проекта: 30 минут — время существования подтверждённого холда. Отсчёт начинается после подтверждения холда в 1С. Если холд продолжает действовать 30 минут, создаётся Alert и отправляется уведомление ответственному. Уведомление не снимает холд и не завершает оформление/оплату заказа.': ''}
