 if(!v.scenarios.length||v.scenarios.length>12)throw fail('Не выполнен сценарный разбор');for(const c of v.scenarios){if(!groundedQuote(source,c.sourceQuote))throw fail('Сценарий не подтверждён источником')}if(v.scenarios.some(c=>c.result==='fail')&&!v.violations.length)throw fail('Сценарные ошибки не включены в результат проверки'); if(v.ok!==(v.violations.length===0))throw fail('Несогласованный итог сценарной проверки');if(v.violations.length>6)throw fail('Слишком много замечаний проверки');const issues=[];for(const x of v.violations){clean(x.reason,600,'Замечание');const quote=clean(x.sourceQuote,1000,'Цитата проверки');if(!groundedQuote(source,quote))throw fail('Замечание проверки не подтверждено источником');const process=plan.processes.find(p=>p.id===x.process),node=process?.nodes?.find(n=>n.id===x.node),reference=process?' ['+process.id+(node?'/'+node.id:'')+']':'';if(/не (?:является )?нарушени|это допустим/i.test(x.reason))continue;issues.push(x.ruleId+reference+': '+x.reason)}if(v.scenarios.some(c=>c.result==='fail')&&!issues.length)throw fail('Проверка содержит неразрешённый отрицательный сценарий');return{ok:!issues.length,issues,questions:[],scenarios:v.scenarios,model:reviewModel,...(options.fallbackFrom?{fallbackFrom:options.fallbackFrom}:{})};
