 if(!hasGraph){
  analyses=analyses.filter(a=>{const chunk=chunks.find(c=>c.id===a?.chunk);if(!chunk)return false;try{validateExtraction(a.result,chunk);return true}catch{return false}});
  for(let i=0;i<chunks.length;i+=2){const pending=chunks.slice(i,i+2).filter(c=>!analyses.some(a=>a.chunk===c.id));if(!pending.length)continue;await checkpoint('extract',0);
   const results=await Promise.allSettled(pending.map(async chunk=>{const step=chunks.indexOf(chunk)+1;const result=await extractRequirements(chunk,key,fetcher,{budget,recovery,onProgress:e=>progress({...e,step,steps:chunks.length})});analyses.push({chunk:chunk.id,result});await checkpoint('extract',0)}));
   const failure=results.find(r=>r.status==='rejected');if(failure)throw failure.reason;
  }
 }

 const initialMessages=[{role:'system',content:flatSystem+'\n'+bpmnInstructions(source)},{role:'user',content:JSON.stringify({requirements:requirements.map(({id,quote})=>({id,quote})),analysis:chunks.map(c=>analyses.find(a=>a.chunk===c.id)?.result).filter(Boolean),instruction:'Построй граф сразу. Исходные пункты имеют приоритет над вспомогательным разбором. Сохрани все независимые сценарии и исключения.'})}];
