     let fatal=null;for(let i=0;i<settled.length;i++){if(settled[i].status!=='rejected')continue;const error=settled[i].reason,t=pending[i],smaller=['reasoning_repetition','invalid_evidence_review','timeout','incomplete_stream'].includes(error.providerCode)?splitAudit(t):null;if(smaller){reviewQueue.splice(reviewQueue.findIndex(x=>x.id===t.id),1,...smaller);for(const child of smaller)reviewSignatures[child.id]=auditSignature(source,raw,child);await checkpoint('review',attempt,{raw});await progress({stage:'review',retrying:true,recovery:'split',steps:reviewQueue.length,completed:Object.keys(reviewResults).length})}else fatal||=error}
